SELECT fm.id, fm.code as code, qssr.id as skuRefId, qssr.sku_id as skuId, qssr.sku_no as skuNo, fm.file_type as fileType, fm.first_category_id as firstCategoryId, fm.first_category_name as firstCategoryName, qssr.product_name as productName, a.id as fileId, a.attach_name as attachName, a.attach_version as attachVersion, a.attach_url as attachUrl, fm.remark as remark, fm.create_user_name as createUserName, fm.update_user_name as updateUserName, fm.create_time as createTime, fm.update_time as updateTime FROM file_management fm LEFT JOIN attachment a on fm.file_id = a.id and a.is_deleted=false left join qc_standard_sku_ref qssr on fm.id = qssr.main_id and qssr.is_deleted = FALSE where ${params.sqlMap.default} AND fm.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fm.create_time desc

SELECT fm.id,fm.file_type,qssr.sku_id,qssr.sku_no
FROM file_management fm
left join qc_standard_sku_ref qssr on fm.id = qssr.main_id and qssr.is_deleted = FALSE
WHERE fm.is_deleted = FALSE
AND fm.file_type = #{fileType}

    and qssr.sku_id in

        #{item}



    and qssr.sku_id is null


  AND fm.id != #{id}
